from itertools import groupby


def squash(s: str) -> str:
    out = []
    for ch, group in groupby(s):
        count = sum(1 for _ in group)
        escaped = "\\" + ch if ("0" <= ch <= "9" or ch == "\\") else ch
        if count >= 3:
            out.append(f"{count}{escaped}")
        else:
            out.append(escaped * count)
    return "".join(out)
